/**
 * Admin curation actions for the featured-courses widget.
 * @module     local_sentientia_courses/featured
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_sentientia_courses/featured", [
    "core/ajax",
    "core/notification"
], function(Ajax, Notification) {
    "use strict";

    var handleAddSubmit = function(event) {
        event.preventDefault();
        var form = event.currentTarget;
        var courseid = parseInt(
            form.querySelector("#ap-featured-course").value || "0", 10);
        var tenantid = parseInt(
            form.querySelector("#ap-featured-tenant").value || "0", 10);
        var label = (form.querySelector("#ap-featured-label").value || "").trim();
        if (!courseid) {
            Notification.addNotification({
                message: "Please pick a course.",
                type: "warning"
            });
            return;
        }
        Ajax.call([{
            methodname: "local_sentientia_courses_add_featured",
            args: {courseid: courseid, costcenterid: tenantid, label: label}
        }])[0].then(function() {
            Notification.addNotification({
                message: "Pinned to featured.",
                type: "success"
            });
            window.location.reload();
            return null;
        }).catch(Notification.exception);
    };

    var confirmRemove = function(rowid, courseName, returnFocus) {
        Notification.deleteCancelPromise(
            "Unpin from featured",
            'Remove "' + courseName + '" from the featured-courses widget?',
            "Remove", returnFocus).then(function() {
            Ajax.call([{
                methodname: "local_sentientia_courses_remove_featured",
                args: {id: rowid}
            }])[0].then(function() {
                Notification.addNotification({
                    message: "Unpinned.",
                    type: "success"
                });
                window.location.reload();
                return null;
            }).catch(Notification.exception);
            return true;
        }, function() { return null; });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        if (action === "remove-featured") {
            event.preventDefault();
            var rowid = parseInt(trigger.dataset.rowid || "0", 10);
            var name = trigger.dataset.course || "this course";
            confirmRemove(rowid, name, trigger);
        }
    };

    return {
        init: function() {
            var form = document.getElementById("ap-featured-add");
            if (form && form.dataset.airpayInit !== "1") {
                form.dataset.airpayInit = "1";
                form.addEventListener("submit", handleAddSubmit);
            }
            var root = document.querySelector(
                '[data-region="ap-featured-admin"]');
            if (root && root.dataset.airpayClickInit !== "1") {
                root.dataset.airpayClickInit = "1";
                root.addEventListener("click", handleClick);
            }
        }
    };
});
